#studio-export{--p-bg:#f4f6fb;--p-panel:#fff;--p-soft:#edf2f9;--p-ink:#1b263d;--p-muted:#61708a;--p-line:#dce4ef;--p-accent:#2563eb;--p-gap:16px;--p-radius:12px;--p-ms:240ms;color:var(--p-ink);background:var(--p-bg);font:13px/1.5 'Segoe UI','Microsoft YaHei',sans-serif;min-height:405px;container-type:inline-size;border:1px solid var(--p-line);border-radius:12px;overflow:clip}
#studio-export *{box-sizing:border-box}#studio-export button,#studio-export input{font:inherit}#studio-export button{cursor:pointer}#studio-export button:focus-visible,#studio-export summary:focus-visible,#studio-export input:focus-visible{outline:2px solid var(--p-accent);outline-offset:2px}#studio-export .p-app{display:grid;grid-template-columns:124px minmax(0,1fr);min-height:405px}#studio-export .p-nav{display:flex;flex-direction:column;gap:6px;background:var(--p-panel);border-right:1px solid var(--p-line);padding:18px 11px}#studio-export .p-wordmark{font-weight:700;padding:0 6px 19px;overflow-wrap:anywhere}#studio-export .p-nav button{border:0;background:transparent;color:var(--p-muted);text-align:left;padding:9px;border-radius:var(--p-radius);font-size:11px}#studio-export .p-nav button.is-active{background:var(--p-soft);color:var(--p-accent);font-weight:600}#studio-export .p-main{min-width:0;padding:20px;display:flex;flex-direction:column;gap:var(--p-gap)}#studio-export .p-hero h2{font-size:23px;line-height:1.2;letter-spacing:-.04em;margin:0 0 9px}#studio-export .p-hero p{font-size:11px;color:var(--p-muted);margin:0}#studio-export .p-hero small{display:block;color:var(--p-accent);font-size:10px;letter-spacing:.08em;margin-bottom:10px}#studio-export .p-search{width:100%;padding:10px 12px;color:var(--p-ink);background:var(--p-panel);border:1px solid var(--p-line);border-radius:var(--p-radius)}#studio-export .p-filters{display:flex;flex-wrap:wrap;gap:7px}#studio-export .p-filters button{border:1px solid var(--p-line);background:var(--p-panel);color:var(--p-muted);border-radius:24px;padding:5px 11px;font-size:11px}#studio-export .p-filters button.is-active{border-color:var(--p-accent);color:var(--p-accent)}#studio-export .p-items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--p-gap);min-width:0}#studio-export.p-cols-2 .p-items{grid-template-columns:repeat(2,minmax(0,1fr))}#studio-export.p-cols-4 .p-items{grid-template-columns:repeat(4,minmax(0,1fr))}#studio-export .p-item{min-width:0;border:1px solid var(--p-line);border-radius:var(--p-radius);background:var(--p-panel);overflow:hidden;transition:transform var(--p-ms),box-shadow var(--p-ms)}#studio-export .p-item[hidden]{display:none!important}#studio-export .p-item-main{display:block;width:100%;border:0;text-align:left;color:var(--p-ink);background:transparent;padding:15px;min-height:100px}#studio-export .p-item-tag{display:block;font-size:9px;color:var(--p-accent);margin-bottom:13px;text-transform:uppercase;letter-spacing:.08em}#studio-export .p-item h3{font-size:13px;margin:0 0 7px;font-weight:600;overflow-wrap:anywhere}#studio-export .p-item small{font-size:10px;color:var(--p-muted)}#studio-export .p-item-more{padding:0 15px 15px;color:var(--p-muted);font-size:11px;animation:p-reveal var(--p-ms) ease}#studio-export .p-item.is-open{border-color:var(--p-accent)}#studio-export .p-detail{border:1px solid var(--p-line);background:var(--p-panel);border-radius:var(--p-radius);padding:16px;font-size:11px;color:var(--p-muted);min-width:0}#studio-export .p-detail h3{color:var(--p-ink);font-size:15px;margin:0 0 9px}#studio-export .p-detail p{margin:6px 0}#studio-export .p-detail code{word-break:break-word}#studio-export .p-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--p-line);padding-top:12px;font-size:10px;color:var(--p-muted)}#studio-export .p-rail.p-app{grid-template-columns:58px minmax(0,1fr)}#studio-export .p-rail .p-wordmark{padding:0 4px 12px;font-size:16px}#studio-export .p-rail .p-nav button{font-size:10px;text-align:center;padding:9px 0}#studio-export .p-top.p-app{grid-template-columns:minmax(0,1fr)}#studio-export .p-top .p-nav{flex-direction:row;align-items:center;border-right:0;border-bottom:1px solid var(--p-line);padding:10px 15px;gap:10px}#studio-export .p-top .p-wordmark{padding:0;margin-right:auto;font-size:12px}#studio-export .p-none.p-app{grid-template-columns:minmax(0,1fr)}#studio-export .p-none>.p-nav{display:none}#studio-export.p-metro .p-item{border-radius:3px}#studio-export.p-metro .p-item:first-child{grid-column:span 2;background:var(--p-accent);color:#fff;border-color:var(--p-accent)}#studio-export.p-metro .p-item:first-child .p-item-main{color:#fff}#studio-export.p-metro .p-item:first-child small,#studio-export.p-metro .p-item:first-child .p-item-tag,#studio-export.p-metro .p-item:first-child .p-item-more{color:#fff;opacity:.9}#studio-export.p-masonry .p-items{display:block;columns:3;column-gap:var(--p-gap)}#studio-export.p-masonry .p-item{break-inside:avoid;margin-bottom:var(--p-gap)}#studio-export.p-masonry .p-item:nth-child(3n) .p-item-main{min-height:160px}#studio-export.p-masonry .p-item:nth-child(3n+1) .p-item-main{min-height:130px}#studio-export.p-cols-2.p-masonry .p-items{columns:2}#studio-export.p-cols-4.p-masonry .p-items{columns:4}#studio-export.p-list .p-items{display:flex;flex-direction:column;gap:9px}#studio-export.p-list .p-item-main{min-height:70px;padding:12px 14px}#studio-export.p-list .p-item-tag{margin-bottom:4px}#studio-export.p-list .p-content{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(120px,.9fr);gap:var(--p-gap);align-items:start}#studio-export.p-list .p-content>.p-detail{position:sticky;top:10px}#studio-export.p-list .p-item h3{font-size:12px}#studio-export .p-kanban{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}#studio-export .p-lane{background:var(--p-soft);padding:10px;border-radius:var(--p-radius);min-height:160px}#studio-export .p-lane>h3{margin:0 0 12px;font-size:11px;color:var(--p-muted);font-weight:500}#studio-export .p-lane .p-item{margin-bottom:9px}#studio-export .p-lane .p-item-main{padding:12px;min-height:80px}#studio-export .p-canvas{height:310px;position:relative;background-image:radial-gradient(var(--p-line) 1px,transparent 1px);background-size:17px 17px;overflow:hidden;touch-action:none;cursor:grab;border:1px solid var(--p-line);border-radius:var(--p-radius)}#studio-export .p-world{position:absolute;left:0;top:0;width:1400px;height:1000px;transform-origin:0 0}#studio-export .p-world .p-item{position:absolute;width:180px}#studio-export .p-zoom{position:absolute;bottom:9px;right:9px;display:flex;align-items:center;background:var(--p-panel);padding:4px;border:1px solid var(--p-line);border-radius:7px}#studio-export .p-zoom button{padding:5px 8px;border:0;background:var(--p-panel);color:var(--p-ink)}#studio-export .p-zoom output{font-size:10px;padding-inline:5px}#studio-export .p-virtual{height:300px;overflow:auto;overflow-anchor:none;position:relative;scrollbar-width:thin}#studio-export .p-spacer{position:relative}#studio-export .p-virtual .p-item{position:absolute;left:0;right:4px}#studio-export .p-virtual-count{font-size:10px;color:var(--p-muted);margin-bottom:8px}#studio-export.p-hover .p-item:hover{transform:translateY(-3px);box-shadow:0 7px 18px #0f172a16}#studio-export.p-canvas-layout.p-hover .p-world .p-item:hover{box-shadow:0 7px 18px #0f172a16}#studio-export.p-stagger .p-item{animation:p-enter var(--p-ms) both;animation-delay:var(--p-delay,0ms)}#studio-export.p-sticky .p-search-module{position:sticky;top:0;z-index:2;background:var(--p-bg);padding-block:5px}#studio-export.p-drag .p-item{cursor:grab}#studio-export .p-item.is-dragging{opacity:.4}#studio-export.p-compact .p-main{padding:14px}#studio-export.p-compact .p-item-main{padding:11px;min-height:80px}#studio-export.p-compact .p-item h3{font-size:12px}#studio-export.p-focus .p-item:focus-within{outline:2px solid var(--p-accent);outline-offset:3px}#studio-export.p-brutalist{--p-line:#17233a;--p-radius:0px}#studio-export.p-brutalist .p-item{border:2px solid var(--p-ink);box-shadow:4px 4px 0 var(--p-ink)}#studio-export.p-editorial .p-hero h2{font-family:Georgia,'Songti SC','SimSun',serif;font-size:30px;font-weight:500}#studio-export.p-editorial .p-item{border-radius:0;border:0;border-top:1px solid var(--p-line);background:transparent}#studio-export.p-glass{--p-bg:#edf3ff;--p-soft:#e2ecff}#studio-export.p-glass .p-nav,#studio-export.p-glass .p-item{background:#ffffffcc;backdrop-filter:blur(14px)}#studio-export.p-dark{--p-bg:#121923;--p-panel:#1c2737;--p-soft:#253247;--p-ink:#e8eef9;--p-muted:#a5b5cc;--p-line:#37465d}#studio-export.p-dark.p-glass .p-nav,#studio-export.p-dark.p-glass .p-item{background:#1c2737dd}#studio-export .p-result{font-size:10px;color:var(--p-muted)}
@keyframes p-enter{from{opacity:0;translate:0 12px}to{opacity:1;translate:0 0}}@keyframes p-reveal{from{opacity:0;translate:0 -5px}to{opacity:1;translate:0 0}}
@container(max-width:460px){#studio-export .p-app{grid-template-columns:52px minmax(0,1fr)}#studio-export .p-nav{padding:13px 5px}#studio-export .p-wordmark{font-size:10px;padding:0 0 13px}#studio-export .p-nav button{padding:9px 2px;font-size:9px;text-align:center}#studio-export .p-main{padding:14px}#studio-export .p-items{grid-template-columns:repeat(2,minmax(0,1fr))!important}#studio-export.p-masonry .p-items{columns:2}#studio-export .p-item-main{padding:11px}#studio-export .p-item h3{font-size:11px}#studio-export .p-hero h2{font-size:21px}#studio-export.p-list .p-content{grid-template-columns:minmax(0,1fr)}#studio-export .p-kanban{grid-template-columns:minmax(0,1fr)}#studio-export .p-top .p-nav{flex-wrap:wrap;gap:3px}#studio-export .p-top .p-wordmark{flex-basis:100%}}
@media(prefers-reduced-motion:reduce){#studio-export *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:13px/1.55 'Segoe UI','Microsoft YaHei',sans-serif}button,input,select,textarea{font:inherit}button,select,input[type=checkbox],input[type=range],input[type=color]{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}button{background:var(--panel);color:var(--ink-2);border:1px solid var(--line);border-radius:7px;padding:7px 10px}button:hover{border-color:var(--accent);color:var(--accent)}input,textarea,select{min-width:0;background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:7px 9px}textarea{resize:vertical}.studio-primary{background:var(--accent);color:#fff;border-color:var(--accent)}.studio-primary:hover{color:#fff;filter:brightness(1.05)}#design-studio{padding:23px;min-width:0}.studio-heading{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:22px}.studio-eyebrow{font-size:10px;letter-spacing:.12em;color:var(--accent);font-weight:600}.studio-heading h1{font-size:25px;letter-spacing:-.035em;line-height:1.3;font-weight:650;margin:8px 0}.studio-heading p{font-size:12px;color:var(--muted);margin:0}.studio-version{font-size:10px;color:var(--muted);white-space:nowrap;margin-top:4px}.preset-bar{display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:13px 15px;background:var(--panel);border:1px solid var(--line);border-radius:10px;margin-bottom:17px}.preset-bar label{display:flex;align-items:center;gap:10px;font-size:11px;color:var(--muted)}.preset-bar select{max-width:200px}.preset-divider{height:22px;border-left:1px solid var(--line);margin-inline:3px}.preset-bar input{width:160px;font-size:12px}.preset-bar button{font-size:11px}.preset-bar>span:last-child{font-size:10px;color:var(--muted);margin-left:auto}.studio-message{border-left:3px solid var(--accent);background:var(--accent-soft);color:var(--ink-2);padding:10px 13px;font-size:12px;margin-bottom:15px;border-radius:0 7px 7px 0}.studio-message.is-error{border-color:#d34d4d;background:var(--panel);color:#bb3838}.studio-columns{display:grid;grid-template-columns:177px minmax(0,1fr) 190px;gap:15px;align-items:stretch}.studio-library,.studio-inspector{min-width:0;padding:15px 12px;background:var(--panel);border:1px solid var(--line);border-radius:10px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:17px}.section-heading h2{font-size:13px;font-weight:600;margin:0}.section-heading>span{font-size:10px;color:var(--muted)}.library-section{margin-bottom:17px}.library-section summary{font-size:11px;font-weight:600;color:var(--ink-2);cursor:pointer;list-style:none;padding:4px 0 9px;display:flex;align-items:center;gap:6px}.library-section summary:before{content:'›';display:inline-block;transform:rotate(0deg);color:var(--muted)}.library-section[open] summary:before{transform:rotate(90deg)}.library-choices{display:grid;grid-template-columns:1fr 1fr;gap:6px}.library-choice{font-size:10px;min-height:49px;padding:7px 5px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;border-radius:7px;text-align:center}.library-choice .choice-symbol{font-size:16px;line-height:1}.library-choice[aria-pressed=true]{color:var(--accent);border-color:var(--accent);background:var(--accent-soft)}.library-effects{display:flex;flex-direction:column;gap:7px}.library-effects label{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--ink-2)}.library-effects input{margin:0;accent-color:var(--accent)}.library-caption{font-size:10px;color:var(--muted);margin:9px 0 0;line-height:1.7}.studio-preview-area{min-width:0;display:flex;flex-direction:column}.preview-heading{display:flex;justify-content:space-between;gap:10px;align-items:center;margin:2px 0 15px}.preview-heading h2{font-size:15px;font-weight:600;margin:3px 0 0}.preview-heading .studio-eyebrow{font-size:9px}.preview-controls{display:flex;align-items:center;gap:7px;flex-wrap:wrap;justify-content:flex-end}.preview-controls label{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:10px}.preview-controls select,.preview-controls button{font-size:10px;padding:6px 8px}#preview-container{background:var(--panel-soft);padding:12px;border:1px solid var(--line);border-radius:11px;min-height:450px;max-height:740px;overflow:auto;display:flex;align-items:flex-start;justify-content:center;scrollbar-width:thin}#studio-export{width:100%;flex-shrink:0}#preview-container.is-mobile #studio-export{max-width:360px}#preview-container.is-tablet #studio-export{max-width:650px}.preview-caption{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;margin:12px 1px;color:var(--muted);font-size:10px}.combination-notes{margin-top:auto;padding:10px 12px;border:1px dashed var(--line);border-radius:8px;color:var(--muted);font-size:10px;line-height:1.9}.combination-notes strong{font-weight:600;color:var(--ink-2)}.studio-inspector>label,.inspector-pair>label{display:flex;flex-direction:column;gap:6px;font-size:11px;color:var(--muted);margin-bottom:13px}.studio-inspector input:not([type=range]):not([type=color]),.studio-inspector select,.studio-inspector textarea{width:100%;font-size:12px}.studio-inspector textarea{font-size:11px;min-height:65px}.inspector-pair{display:grid;grid-template-columns:1fr 1fr;gap:9px}.studio-inspector output{align-self:flex-end;float:right;margin-top:-22px;font-size:10px;font-variant-numeric:tabular-nums;color:var(--ink-2)}.studio-inspector input[type=range]{padding:0;border:0;width:100%;accent-color:var(--accent)}.studio-inspector input[type=color]{height:33px;width:100%;padding:3px}.studio-modules{border-top:1px solid var(--line);padding-top:13px}.studio-modules h3{font-size:11px;margin:0 0 10px;font-weight:600}.studio-modules p{font-size:10px;color:var(--muted);margin:8px 0 0}.module-row{display:flex;align-items:center;gap:4px;margin-bottom:5px}.module-row label{display:flex;align-items:center;gap:5px;min-width:0;flex:1;font-size:10px;color:var(--ink-2)}.module-row input{accent-color:var(--accent);margin:0}.module-row button{font-size:11px;padding:2px 5px;border:0;background:var(--panel-soft);color:var(--muted)}.studio-output{margin-top:20px;border:1px solid var(--line);border-radius:10px;background:var(--panel);padding:15px}.output-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap;margin-bottom:14px}.output-tabs{display:flex;flex-wrap:wrap;gap:5px}.output-tabs button{border-color:transparent;font-size:11px;padding:7px 9px}.output-tabs button[aria-selected=true]{background:var(--accent-soft);color:var(--accent)}.output-actions{display:flex;gap:8px}.output-actions button{font-size:11px}.studio-output>label{display:block;color:var(--muted);font-size:10px;margin-bottom:8px}.studio-output>textarea{width:100%;height:240px;font:11px/1.7 'Cascadia Code',Consolas,'Microsoft YaHei',monospace;padding:14px;background:var(--panel-soft);color:var(--ink-2);border-radius:7px;white-space:pre;overflow:auto}.studio-output>p{font-size:10px;color:var(--muted);margin:8px 0 0}.studio-dialog-overlay{position:fixed;inset:0;z-index:30;background:#0f172a77;display:grid;place-items:center;padding:22px}.studio-dialog-overlay[hidden]{display:none}.studio-dialog{background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:12px;width:min(620px,100%);padding:22px}.studio-dialog h2{font-size:18px;margin:0 0 10px}.studio-dialog p{font-size:12px;color:var(--muted)}.studio-dialog textarea{width:100%;height:200px;font:12px/1.6 monospace}.studio-dialog>div{display:flex;justify-content:flex-end;gap:10px}.studio-dialog #import-error{color:#bc3636;min-height:18px}.preview-maximized .studio-columns{grid-template-columns:minmax(0,1fr)}
@media(max-width:1000px){.studio-columns{grid-template-columns:150px minmax(0,1fr)}.studio-inspector{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px 15px}.studio-inspector .section-heading{grid-column:1/-1;margin-bottom:0}.studio-inspector>label,.studio-inspector .inspector-pair>label{margin-bottom:0}.studio-inspector>.inspector-pair{display:contents}.studio-modules{grid-column:1/-1}.studio-modules #module-order{display:flex;flex-wrap:wrap;gap:12px}.module-row{min-width:145px}.studio-version{display:none}.preset-bar>span:last-child{flex-basis:100%;margin-left:0}.preset-divider{display:none}}
@media(max-width:640px){#design-studio{padding:15px}.studio-heading h1{font-size:21px}.studio-columns{grid-template-columns:minmax(0,1fr)}.studio-library{display:block}.studio-library #library-content{display:grid;grid-template-columns:1fr 1fr;gap:9px 15px}.library-section{margin-bottom:5px}.library-section:last-child{grid-column:1/-1}.library-effects{gap:8px}.library-choices{grid-template-columns:1fr 1fr}.studio-inspector{grid-template-columns:repeat(2,minmax(0,1fr))}#preview-container{padding:7px;min-height:400px}.output-actions{flex-wrap:wrap}.preset-bar input{width:100%;flex:1 1 150px}.preset-bar label{flex-wrap:wrap}.studio-output{padding:12px}.studio-output>textarea{font-size:12px}.studio-modules #module-order{display:block}.module-row{width:100%}.studio-dialog{padding:15px}.studio-dialog-overlay{padding:12px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
.studio-inspector>.inspector-switch{flex-direction:row;align-items:center;gap:8px}.studio-inspector .inspector-switch input{width:auto!important;accent-color:var(--accent)}

views.script:
globalThis.DESIGN_PREVIEW_CSS="#studio-export{--p-bg:#f4f6fb;--p-panel:#fff;--p-soft:#edf2f9;--p-ink:#1b263d;--p-muted:#61708a;--p-line:#dce4ef;--p-accent:#2563eb;--p-gap:16px;--p-radius:12px;--p-ms:240ms;color:var(--p-ink);background:var(--p-bg);font:13px/1.5 'Segoe UI','Microsoft YaHei',sans-serif;min-height:405px;container-type:inline-size;border:1px solid var(--p-line);border-radius:12px;overflow:clip}\n#studio-export *{box-sizing:border-box}#studio-export button,#studio-export input{font:inherit}#studio-export button{cursor:pointer}#studio-export button:focus-visible,#studio-export summary:focus-visible,#studio-export input:focus-visible{outline:2px solid var(--p-accent);outline-offset:2px}#studio-export .p-app{display:grid;grid-template-columns:124px minmax(0,1fr);min-height:405px}#studio-export .p-nav{display:flex;flex-direction:column;gap:6px;background:var(--p-panel);border-right:1px solid var(--p-line);padding:18px 11px}#studio-export .p-wordmark{font-weight:700;padding:0 6px 19px;overflow-wrap:anywhere}#studio-export .p-nav button{border:0;background:transparent;color:var(--p-muted);text-align:left;padding:9px;border-radius:var(--p-radius);font-size:11px}#studio-export .p-nav button.is-active{background:var(--p-soft);color:var(--p-accent);font-weight:600}#studio-export .p-main{min-width:0;padding:20px;display:flex;flex-direction:column;gap:var(--p-gap)}#studio-export .p-hero h2{font-size:23px;line-height:1.2;letter-spacing:-.04em;margin:0 0 9px}#studio-export .p-hero p{font-size:11px;color:var(--p-muted);margin:0}#studio-export .p-hero small{display:block;color:var(--p-accent);font-size:10px;letter-spacing:.08em;margin-bottom:10px}#studio-export .p-search{width:100%;padding:10px 12px;color:var(--p-ink);background:var(--p-panel);border:1px solid var(--p-line);border-radius:var(--p-radius)}#studio-export .p-filters{display:flex;flex-wrap:wrap;gap:7px}#studio-export .p-filters button{border:1px solid var(--p-line);background:var(--p-panel);color:var(--p-muted);border-radius:24px;padding:5px 11px;font-size:11px}#studio-export .p-filters button.is-active{border-color:var(--p-accent);color:var(--p-accent)}#studio-export .p-items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--p-gap);min-width:0}#studio-export.p-cols-2 .p-items{grid-template-columns:repeat(2,minmax(0,1fr))}#studio-export.p-cols-4 .p-items{grid-template-columns:repeat(4,minmax(0,1fr))}#studio-export .p-item{min-width:0;border:1px solid var(--p-line);border-radius:var(--p-radius);background:var(--p-panel);overflow:hidden;transition:transform var(--p-ms),box-shadow var(--p-ms)}#studio-export .p-item[hidden]{display:none!important}#studio-export .p-item-main{display:block;width:100%;border:0;text-align:left;color:var(--p-ink);background:transparent;padding:15px;min-height:100px}#studio-export .p-item-tag{display:block;font-size:9px;color:var(--p-accent);margin-bottom:13px;text-transform:uppercase;letter-spacing:.08em}#studio-export .p-item h3{font-size:13px;margin:0 0 7px;font-weight:600;overflow-wrap:anywhere}#studio-export .p-item small{font-size:10px;color:var(--p-muted)}#studio-export .p-item-more{padding:0 15px 15px;color:var(--p-muted);font-size:11px;animation:p-reveal var(--p-ms) ease}#studio-export .p-item.is-open{border-color:var(--p-accent)}#studio-export .p-detail{border:1px solid var(--p-line);background:var(--p-panel);border-radius:var(--p-radius);padding:16px;font-size:11px;color:var(--p-muted);min-width:0}#studio-export .p-detail h3{color:var(--p-ink);font-size:15px;margin:0 0 9px}#studio-export .p-detail p{margin:6px 0}#studio-export .p-detail code{word-break:break-word}#studio-export .p-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--p-line);padding-top:12px;font-size:10px;color:var(--p-muted)}#studio-export .p-rail.p-app{grid-template-columns:58px minmax(0,1fr)}#studio-export .p-rail .p-wordmark{padding:0 4px 12px;font-size:16px}#studio-export .p-rail .p-nav button{font-size:10px;text-align:center;padding:9px 0}#studio-export .p-top.p-app{grid-template-columns:minmax(0,1fr)}#studio-export .p-top .p-nav{flex-direction:row;align-items:center;border-right:0;border-bottom:1px solid var(--p-line);padding:10px 15px;gap:10px}#studio-export .p-top .p-wordmark{padding:0;margin-right:auto;font-size:12px}#studio-export .p-none.p-app{grid-template-columns:minmax(0,1fr)}#studio-export .p-none>.p-nav{display:none}#studio-export.p-metro .p-item{border-radius:3px}#studio-export.p-metro .p-item:first-child{grid-column:span 2;background:var(--p-accent);color:#fff;border-color:var(--p-accent)}#studio-export.p-metro .p-item:first-child .p-item-main{color:#fff}#studio-export.p-metro .p-item:first-child small,#studio-export.p-metro .p-item:first-child .p-item-tag,#studio-export.p-metro .p-item:first-child .p-item-more{color:#fff;opacity:.9}#studio-export.p-masonry .p-items{display:block;columns:3;column-gap:var(--p-gap)}#studio-export.p-masonry .p-item{break-inside:avoid;margin-bottom:var(--p-gap)}#studio-export.p-masonry .p-item:nth-child(3n) .p-item-main{min-height:160px}#studio-export.p-masonry .p-item:nth-child(3n+1) .p-item-main{min-height:130px}#studio-export.p-cols-2.p-masonry .p-items{columns:2}#studio-export.p-cols-4.p-masonry .p-items{columns:4}#studio-export.p-list .p-items{display:flex;flex-direction:column;gap:9px}#studio-export.p-list .p-item-main{min-height:70px;padding:12px 14px}#studio-export.p-list .p-item-tag{margin-bottom:4px}#studio-export.p-list .p-content{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(120px,.9fr);gap:var(--p-gap);align-items:start}#studio-export.p-list .p-content>.p-detail{position:sticky;top:10px}#studio-export.p-list .p-item h3{font-size:12px}#studio-export .p-kanban{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}#studio-export .p-lane{background:var(--p-soft);padding:10px;border-radius:var(--p-radius);min-height:160px}#studio-export .p-lane>h3{margin:0 0 12px;font-size:11px;color:var(--p-muted);font-weight:500}#studio-export .p-lane .p-item{margin-bottom:9px}#studio-export .p-lane .p-item-main{padding:12px;min-height:80px}#studio-export .p-canvas{height:310px;position:relative;background-image:radial-gradient(var(--p-line) 1px,transparent 1px);background-size:17px 17px;overflow:hidden;touch-action:none;cursor:grab;border:1px solid var(--p-line);border-radius:var(--p-radius)}#studio-export .p-world{position:absolute;left:0;top:0;width:1400px;height:1000px;transform-origin:0 0}#studio-export .p-world .p-item{position:absolute;width:180px}#studio-export .p-zoom{position:absolute;bottom:9px;right:9px;display:flex;align-items:center;background:var(--p-panel);padding:4px;border:1px solid var(--p-line);border-radius:7px}#studio-export .p-zoom button{padding:5px 8px;border:0;background:var(--p-panel);color:var(--p-ink)}#studio-export .p-zoom output{font-size:10px;padding-inline:5px}#studio-export .p-virtual{height:300px;overflow:auto;overflow-anchor:none;position:relative;scrollbar-width:thin}#studio-export .p-spacer{position:relative}#studio-export .p-virtual .p-item{position:absolute;left:0;right:4px}#studio-export .p-virtual-count{font-size:10px;color:var(--p-muted);margin-bottom:8px}#studio-export.p-hover .p-item:hover{transform:translateY(-3px);box-shadow:0 7px 18px #0f172a16}#studio-export.p-canvas-layout.p-hover .p-world .p-item:hover{box-shadow:0 7px 18px #0f172a16}#studio-export.p-stagger .p-item{animation:p-enter var(--p-ms) both;animation-delay:var(--p-delay,0ms)}#studio-export.p-sticky .p-search-module{position:sticky;top:0;z-index:2;background:var(--p-bg);padding-block:5px}#studio-export.p-drag .p-item{cursor:grab}#studio-export .p-item.is-dragging{opacity:.4}#studio-export.p-compact .p-main{padding:14px}#studio-export.p-compact .p-item-main{padding:11px;min-height:80px}#studio-export.p-compact .p-item h3{font-size:12px}#studio-export.p-focus .p-item:focus-within{outline:2px solid var(--p-accent);outline-offset:3px}#studio-export.p-brutalist{--p-line:#17233a;--p-radius:0px}#studio-export.p-brutalist .p-item{border:2px solid var(--p-ink);box-shadow:4px 4px 0 var(--p-ink)}#studio-export.p-editorial .p-hero h2{font-family:Georgia,'Songti SC','SimSun',serif;font-size:30px;font-weight:500}#studio-export.p-editorial .p-item{border-radius:0;border:0;border-top:1px solid var(--p-line);background:transparent}#studio-export.p-glass{--p-bg:#edf3ff;--p-soft:#e2ecff}#studio-export.p-glass .p-nav,#studio-export.p-glass .p-item{background:#ffffffcc;backdrop-filter:blur(14px)}#studio-export.p-dark{--p-bg:#121923;--p-panel:#1c2737;--p-soft:#253247;--p-ink:#e8eef9;--p-muted:#a5b5cc;--p-line:#37465d}#studio-export.p-dark.p-glass .p-nav,#studio-export.p-dark.p-glass .p-item{background:#1c2737dd}#studio-export .p-result{font-size:10px;color:var(--p-muted)}\n@keyframes p-enter{from{opacity:0;translate:0 12px}to{opacity:1;translate:0 0}}@keyframes p-reveal{from{opacity:0;translate:0 -5px}to{opacity:1;translate:0 0}}\n@container(max-width:460px){#studio-export .p-app{grid-template-columns:52px minmax(0,1fr)}#studio-export .p-nav{padding:13px 5px}#studio-export .p-wordmark{font-size:10px;padding:0 0 13px}#studio-export .p-nav button{padding:9px 2px;font-size:9px;text-align:center}#studio-export .p-main{padding:14px}#studio-export .p-items{grid-template-columns:repeat(2,minmax(0,1fr))!important}#studio-export.p-masonry .p-items{columns:2}#studio-export .p-item-main{padding:11px}#studio-export .p-item h3{font-size:11px}#studio-export .p-hero h2{font-size:21px}#studio-export.p-list .p-content{grid-template-columns:minmax(0,1fr)}#studio-export .p-kanban{grid-template-columns:minmax(0,1fr)}#studio-export .p-top .p-nav{flex-wrap:wrap;gap:3px}#studio-export .p-top .p-wordmark{flex-basis:100%}}\n@media(prefers-reduced-motion:reduce){#studio-export *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}\n";
(() => {
  'use strict';
  const lists = {
    layout: {grid:'卡片网格',metro:'Metro 磁贴',masonry:'瀑布流',list:'主从列表',canvas:'无限画布',kanban:'任务看板'},
    navigation: {sidebar:'侧边导航',rail:'紧凑图标栏',top:'顶部导航',none:'无导航'},
    appearance: {clean:'简洁工作台',glass:'轻透 Fluent',editorial:'杂志排版',brutalist:'硬边设计'},
    effects: {expand:'卡片展开',hover:'悬停抬升',stagger:'入场错峰',drag:'拖拽排序',sticky:'搜索栏吸顶',focus:'焦点强调'},
    performance: {standard:'标准渲染',virtual:'虚拟列表',culling:'画布视口裁剪'},
    modules: {hero:'标题与简介',search:'内容搜索',filters:'分类筛选',content:'主要内容',footer:'页脚状态'},
    platform: {web:'网页',android:'Android',desktop:'桌面应用'}
  };
  const defaultConfig = {schema:'toolhub.design/v1',title:'我的创作空间',purpose:'整理网站、移动应用与桌面项目，让想法变成可以使用的作品。',platform:'web',viewport:'desktop',layout:'grid',navigation:'sidebar',appearance:'clean',effects:['expand','hover','focus'],performance:'standard',modules:['hero','search','filters','content','footer'],columns:3,radius:12,gap:16,density:'comfortable',accent:'#2563eb',duration:240,dataSize:12,dark:false};
  const clone = value => JSON.parse(JSON.stringify(value));
  function validate(value) {
    if(!value || typeof value!=='object' || Array.isArray(value))throw Error('配置必须为 JSON 对象');
    if(Object.keys(value).some(key=>!Object.hasOwn(defaultConfig,key)) || Object.keys(value).length!==Object.keys(defaultConfig).length)throw Error('配置字段不完整或包含未知字段');
    const c=clone(value);
    if(c.schema!=='toolhub.design/v1')throw Error('仅支持 toolhub.design/v1');
    for(const key of ['title','purpose'])if(typeof c[key]!=='string'||c[key].length>(key==='title'?48:160)||!c[key].trim()||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(c[key]))throw Error('名称与用途须为有效文本');
    for(const key of ['layout','navigation','appearance','performance','platform'])if(typeof c[key]!=='string'||!Object.hasOwn(lists[key],c[key]))throw Error('未知选项：'+key);
    if(!['desktop','tablet','mobile'].includes(c.viewport)||!['comfortable','compact'].includes(c.density)||typeof c.dark!=='boolean')throw Error('画幅、密度或主题无效');
    for(const key of ['effects','modules'])if(!Array.isArray(c[key])||c[key].length>Object.keys(lists[key]).length||new Set(c[key]).size!==c[key].length||c[key].some(item=>typeof item!=='string'||!Object.hasOwn(lists[key],item)))throw Error('效果或模块无效');
    if(!c.modules.includes('content'))throw Error('必须保留主要内容模块');
    if(!Number.isInteger(c.radius)||c.radius<0||c.radius>24||!Number.isInteger(c.gap)||c.gap<8||c.gap>28||![2,3,4].includes(c.columns)||![0,160,240,360,480].includes(c.duration)||![12,100,10000].includes(c.dataSize)||typeof c.accent!=='string'||!/^#[0-9a-f]{6}$/i.test(c.accent))throw Error('设计参数超出支持范围');
    if(c.performance==='virtual'&&c.layout!=='list')throw Error('第一版虚拟渲染适用于主从列表；其他结构使用标准渲染');
    if(c.performance==='culling'&&c.layout!=='canvas')throw Error('视口裁剪适用于无限画布');
    if(c.dataSize===10000&&c.performance!=='virtual')throw Error('一万条示例仅在虚拟列表模式开放');
    if(c.effects.includes('drag')&&(c.performance==='virtual'||c.layout==='canvas'))throw Error('虚拟列表 / 无限画布不启用卡片拖拽排序；画布保留平移');
    return c;
  }
  function normalize(value) {
    const c=clone(value),notes=[];
    if(c.performance==='virtual'&&c.layout!=='list'){c.performance=c.layout==='canvas'?'culling':'standard';notes.push('此结构已改用'+lists.performance[c.performance]+'；虚拟列表需要主从列表。');}
    if(c.performance==='culling'&&c.layout!=='canvas'){c.performance='standard';notes.push('视口裁剪只用于画布，已切回标准渲染。');}
    if(c.dataSize===10000&&c.performance!=='virtual'){c.dataSize=100;notes.push('当前结构使用 100 条示例，避免一次渲染一万条内容。');}
    if(c.effects.includes('drag')&&(c.performance==='virtual'||c.layout==='canvas')){c.effects=c.effects.filter(e=>e!=='drag');notes.push('已关闭此组合的卡片拖拽排序，保留滚动 / 画布平移。');}
    return {config:validate(c),notes};
  }
  function escapeHtml(value) { return String(value).replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character])); }
  function sample(index) { const names=['品牌官网','Android 记账应用','桌面素材管理器','产品展示页','视频剪辑项目','设计参考集','团队知识库','个人作品集','项目启动器','灵感画板','移动端原型','组件文档'];return {id:'project-'+index,name:names[index%names.length]+(index>=12?' '+(index+1):''),type:['design','development','assets'][index%3],label:['设计','开发','素材'][index%3],index}; }
  function card(item,c) {return `<article class="p-item" data-id="${item.id}" data-index="${item.index}" data-type="${item.type}"${c.effects.includes('drag')?' draggable="true"':''}><button type="button" class="p-item-main" aria-expanded="false"><span class="p-item-tag">${item.label} / ${String(item.index+1).padStart(2,'0')}</span><h3>${escapeHtml(item.name)}</h3><small>${c.effects.includes('expand')?'点击展开详情':'点击查看项目'}</small></button><div class="p-item-more" hidden>在「${escapeHtml(c.title)}」中继续这个项目。结构、交互与数据应分别组织；当前内容为演示数据。</div></article>`;}
  function markup(c) {
    const nav=`<nav class="p-nav" aria-label="示例应用导航"><div class="p-wordmark">${c.navigation==='rail'?'◧':escapeHtml(c.title)}</div>${['项目','收藏','归档'].map((label,i)=>`<button type="button" data-nav="${label}" class="${i===0?'is-active':''}" aria-pressed="${i===0}">${label}</button>`).join('')}</nav>`;
    const cards=Array.from({length:c.dataSize===10000?12:c.dataSize},(_,i)=>card(sample(i),c));
    let content=`<div class="p-items">${cards.join('')}</div>`;
    if(c.layout==='list')content=(c.performance==='virtual'?'<div><div class="p-virtual-count" role="status"></div><div class="p-virtual" aria-label="虚拟项目列表"><div class="p-spacer"></div></div></div>':content)+'<aside class="p-detail"><h3>选择一个项目</h3><p>查看项目概览、用途与下一步。</p><p>点击左侧卡片，保留列表上下文。</p></aside>';
    if(c.layout==='canvas')content='<div class="p-canvas" aria-label="项目画布"><div class="p-world"></div><div class="p-zoom"><button type="button" data-zoom="out" aria-label="缩小画布">−</button><output>80%</output><button type="button" data-zoom="in" aria-label="放大画布">＋</button><button type="button" data-zoom="reset">复位</button></div></div><div class="p-virtual-count" role="status"></div>';
    if(c.layout==='kanban')content='<div class="p-kanban">'+['想法','进行中','已完成'].map((name,lane)=>`<section class="p-lane" data-lane="${lane}"><h3>${name}</h3>${cards.filter((_,i)=>i%3===lane).join('')}</section>`).join('')+'</div>';
    const modules={hero:`<header class="p-hero"><small>CREATIVE WORKSPACE</small><h2>${escapeHtml(c.title)}</h2><p>${escapeHtml(c.purpose)}</p></header>`,search:'<div class="p-search-module"><input class="p-search" aria-label="搜索示例项目" placeholder="搜索项目名称…"/></div>',filters:'<div class="p-filters" aria-label="示例内容分类"><button type="button" data-filter="all" class="is-active">全部</button><button type="button" data-filter="design">设计</button><button type="button" data-filter="development">开发</button><button type="button" data-filter="assets">素材</button></div>',content:`<section class="p-content" aria-label="项目内容">${content}</section>`,footer:`<footer class="p-footer"><span>本机示例 · ${c.dataSize.toLocaleString()} 条项目</span><output class="p-result" role="status">等待选择</output></footer>`};
    return `<div class="p-app p-${c.navigation}">${nav}<main class="p-main">${c.modules.map(id=>modules[id]).join('')}</main></div>`;
  }
  function bind(root,c) {
    let expanded=new Set(),query='',filter='all',dragged=null,dispose=()=>{};
    const controller=new AbortController(),listenerOptions={signal:controller.signal};
    const result=text=>{const element=root.querySelector('.p-result');if(element)element.textContent=text;root.dispatchEvent(new CustomEvent('design-preview-status',{detail:text,bubbles:true}));};
    const itemMatches=item=>(filter==='all'||item.type===filter)&&item.name.toLowerCase().includes(query);
    const visible=()=>Array.from({length:c.dataSize},(_,i)=>i).filter(i=>itemMatches(sample(i)));
    let indices=visible(),rerender=()=>{};
    const select=(element)=>{const index=Number(element.dataset.index),item=sample(index);if(c.effects.includes('expand')){expanded.has(index)?expanded.delete(index):expanded.add(index);const open=expanded.has(index);element.classList.toggle('is-open',open);element.querySelector('button').setAttribute('aria-expanded',String(open));element.querySelector('.p-item-more').hidden=!open;}
      const detail=root.querySelector('.p-detail');if(detail){detail.replaceChildren();const heading=document.createElement('h3');heading.textContent=item.name;const summary=document.createElement('p');summary.textContent='类型：'+item.label+' · 该项目是布局演示内容。';const next=document.createElement('p');next.textContent='下一步：结合真实业务替换数据和操作，补齐加载、空状态和错误状态。';detail.append(heading,summary,next);}result('已选择：'+item.name);rerender();};
    root.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.matches('[data-nav]')){root.querySelectorAll('[data-nav]').forEach(item=>{const active=item===button;item.classList.toggle('is-active',active);item.setAttribute('aria-pressed',String(active));});result('导航状态：'+button.dataset.nav+'（示例）');}if(button.classList.contains('p-item-main'))select(button.closest('.p-item'));if(button.matches('[data-filter]')){filter=button.dataset.filter;root.querySelectorAll('[data-filter]').forEach(item=>item.classList.toggle('is-active',item===button));applyFilter();}},listenerOptions);
    function applyFilter(){indices=visible();if(c.performance==='virtual'){const scroll=root.querySelector('.p-virtual');scroll.scrollTop=0;rerender();}else if(c.layout==='canvas'){rerender();}else{root.querySelectorAll('.p-item').forEach(element=>{element.hidden=!itemMatches(sample(Number(element.dataset.index)));});}result('匹配 '+indices.length+' 个项目');}
    root.querySelector('.p-search')?.addEventListener('input',event=>{query=event.target.value.trim().toLowerCase();applyFilter();});
    if(c.effects.includes('drag')){
